<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import type {SkinViewer} from 'skinview3d';
import SettingSwitch from '../controls/SettingSwitch.vue';
import {checkSkinPng,SkinPixels} from './skin-pixels';
const pixels=new SkinPixels(),revision=ref(0),canvas=ref<HTMLCanvasElement>(),preview=ref<HTMLCanvasElement>();
const color=ref('#cd804d'),tool=ref<'brush'|'erase'|'pick'>('brush'),model=ref<'default'|'slim'>('default'),walking=ref(true),legacy=ref(false),busy=ref(false),error=ref(''),notice=ref(''),fileName=ref('三秋叶皮肤.png');
let viewer:SkinViewer|undefined,alive=true,generation=0,last:{x:number;y:number}|null=null,timer:ReturnType<typeof setTimeout>|undefined;
const canUndo=computed(()=>{revision.value;return pixels.canUndo;}),canRedo=computed(()=>{revision.value;return pixels.canRedo;});
function updatePreview(){if(viewer&&canvas.value){try{viewer.loadSkin(canvas.value,{model:model.value});}catch{error.value='3D预览无法更新，仍可编辑并导出PNG。';}}}
function draw(){if(!canvas.value||legacy.value)return;canvas.value.height=64;canvas.value.getContext('2d')!.putImageData(new ImageData(new Uint8ClampedArray(pixels.pixels),64,64),0,0);revision.value++;clearTimeout(timer);timer=setTimeout(updatePreview,80);}
function point(e:PointerEvent){const r=canvas.value!.getBoundingClientRect();return {x:Math.max(0,Math.min(63,Math.floor((e.clientX-r.left)*64/r.width))),y:Math.max(0,Math.min(63,Math.floor((e.clientY-r.top)*64/r.height)))};}
function down(e:PointerEvent){if(legacy.value||busy.value||e.button!==0)return;const p=point(e);if(tool.value==='pick'){color.value=pixels.pick(p.x,p.y);return;}pixels.beginStroke();last=p;canvas.value!.setPointerCapture(e.pointerId);pixels.paint(p.x,p.y,tool.value==='erase'?null:color.value);draw();}
function move(e:PointerEvent){if(!last)return;const p=point(e);pixels.line(last.x,last.y,p.x,p.y,tool.value==='erase'?null:color.value);last=p;draw();}
function end(){if(last){last=null;pixels.endStroke();revision.value++;}}
async function load(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file)return;end();const attempt=++generation;busy.value=true;error.value='';try{const dimensions=checkSkinPng(new Uint8Array(await file.slice(0,33).arrayBuffer()),file.size);const image=await createImageBitmap(file);try{if(!alive||attempt!==generation)return;if(image.width!==dimensions.width||image.height!==dimensions.height)throw Error('PNG解码尺寸不一致');const temp=document.createElement('canvas');temp.width=64;temp.height=image.height;const ctx=temp.getContext('2d');if(!ctx)throw Error('当前环境不支持皮肤画布');ctx.drawImage(image,0,0);const data=ctx.getImageData(0,0,64,image.height);legacy.value=image.height===32;if(!legacy.value)pixels.load(data.data,64,64);canvas.value!.height=image.height;canvas.value!.getContext('2d')!.putImageData(data,0,0);fileName.value=file.name.replace(/\.png$/i,'')+'-已编辑.png';revision.value++;updatePreview();notice.value=legacy.value?'64×32旧皮肤仅预览/原尺寸导出；请导入64×64皮肤进行编辑。':'已读入本机副本；原文件不会被改写。';}finally{image.close();}}catch(e){if(alive&&attempt===generation)error.value=e instanceof Error?e.message:'皮肤读取失败，保留当前画布';}finally{if(alive&&attempt===generation)busy.value=false;}}
function blank(){end();generation++;busy.value=false;legacy.value=false;pixels.load(new Uint8ClampedArray(64*64*4),64,64);draw();notice.value='已新建透明64×64画布。导出前请完成所需部位。';}
function undo(){end();pixels.undo();draw();}function redo(){end();pixels.redo();draw();}
function save(){end();const source=canvas.value;if(!source)return;source.toBlob(blob=>{if(!blob||!alive){if(alive)error.value='PNG导出失败';return;}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=fileName.value;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);notice.value='已发起PNG保存；尚未上传账号或更改游戏皮肤。';},'image/png');}
function visibility(){if(viewer)viewer.renderPaused=document.hidden;}
onMounted(async()=>{draw();await nextTick();try{const lib=await import('skinview3d');if(!alive||!preview.value)return;viewer=new lib.SkinViewer({canvas:preview.value,width:280,height:350,skin:canvas.value,model:model.value});viewer.animation=new lib.WalkingAnimation();viewer.animation.paused=!walking.value;viewer.autoRotate=false;visibility();}catch{if(alive)error.value='3D预览未能启用，仍可编辑与导出；请检查显卡/WebGL支持。';}if(alive)document.addEventListener('visibilitychange',visibility);});
watch(model,updatePreview);watch(walking,v=>{if(viewer?.animation)viewer.animation.paused=!v;});
onBeforeUnmount(()=>{alive=false;generation++;clearTimeout(timer);document.removeEventListener('visibilitychange',visibility);viewer?.dispose();});
</script>
<template><section class="skin-tool" aria-label="本机皮肤编辑器"><header><h2>皮肤编辑器</h2><p>在本机编辑自己的皮肤，导出PNG后用于支持自定义皮肤的账号服务。</p></header><p v-if="error" role="alert" class="launcher-inline-notice">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><div class="skin-toolbar"><label class="launcher-secondary skin-file">导入PNG<input type="file" accept="image/png,.png" data-skin-file :disabled="busy" @change="load"/></label><button class="launcher-secondary" data-skin-new :disabled="busy" @click="blank">新建透明皮肤</button><label>工具<select v-model="tool" :disabled="legacy"><option value="brush">画笔</option><option value="erase">橡皮</option><option value="pick">取色</option></select></label><label>颜色<input v-model="color" type="color" data-skin-color/></label><button :disabled="!canUndo||legacy||busy" data-skin-undo @click="undo">撤销</button><button :disabled="!canRedo||legacy||busy" data-skin-redo @click="redo">重做</button><button class="launcher-primary" data-skin-export :disabled="busy" @click="save">导出PNG</button></div><div class="skin-workspace"><div><p>像素画布 · 64×{{legacy?32:64}}<span v-if="legacy"> · 旧格式只读</span></p><canvas ref="canvas" width="64" height="64" class="skin-pixels" :class="{readonly:legacy}" aria-label="皮肤像素画布" data-skin-canvas @pointerdown="down" @pointermove="move" @pointerup="end" @pointercancel="end" @lostpointercapture="end"/><p class="launcher-caption">画布展开显示所有部位；拖动画笔连续绘制，右侧可旋转查看结果。最近32步可撤销。</p></div><aside><canvas ref="preview" data-skin-preview aria-label="3D皮肤预览"/><label>手臂模型<select v-model="model" data-skin-model><option value="default">标准</option><option value="slim">纤细</option></select></label><SettingSwitch v-model="walking" label="行走动画"/></aside></div><p class="launcher-caption">支持64×64编辑；64×32原尺寸只读预览/导出。此工具不自动上传、替换正版皮肤，也不宣称离线皮肤已在游戏生效；账号认证与游戏端换肤独立接入。图片留在本机，不联网。</p></section></template>
<style scoped>.skin-tool{padding:24px}.skin-tool p{line-height:1.8}.skin-toolbar{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:24px 0}.skin-toolbar label,.skin-workspace aside label{display:flex;align-items:center;gap:8px}.skin-file{cursor:pointer;position:relative}.skin-file input{position:absolute;inset:0;opacity:0;width:100%;cursor:pointer}.skin-workspace{display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:28px}.skin-pixels{width:100%;max-width:512px;height:auto;image-rendering:pixelated;touch-action:none;background:repeating-conic-gradient(#89968a40 0% 25%,#24382e50 0% 50%) 0 0/16px 16px;border:1px solid #8a9f8c55;cursor:crosshair}.skin-pixels.readonly{cursor:default}.skin-tool button,.skin-tool select{padding:10px;border:1px solid #8a9f8c44;border-radius:8px}.skin-tool select{background:#182c24;color:inherit}.skin-workspace aside{display:grid;align-content:start;gap:16px}.skin-workspace aside canvas{max-width:100%;height:auto;background:#10251b60;border:1px solid #8a9f8c33;border-radius:14px}.skin-tool button:disabled{opacity:.4}@media(max-width:1100px){.skin-workspace{grid-template-columns:1fr}.skin-workspace aside{grid-row:1;justify-items:start}}</style>
